// Pure FIFO pick-log evidence logic -- no network, no DOM, no filesystem.
// Ports fifo_pick_evidence.py's check_rows/read_report rules (missing-data,
// invalid-timestamp, time-order, fifo-exception, and the headers-only-is-a
// clean-zero-row-report fix) so the browser tool and the CLI agree on every
// verdict. Loadable as a plain <script> in the browser (defines globals, no
// bundler) and requireable under `node --test`.

const REQUIRED = ["order_id", "sku", "lot", "received_at", "picked_at"];

const LIMITATIONS = [
  "This report is an observation of the supplied rows, not an audit conclusion, compliance determination, or chain-of-custody record.",
  "It cannot see picks that never made it into the log, or a warehouse system's own internal semantics -- confirm those before relying on a finding.",
  "Timestamps must include a timezone (for example a trailing Z or +00:00); a bare local timestamp is reported as invalid rather than guessed at.",
];

const TZ_RE = /(Z|[+-]\d{2}:\d{2})$/;

/** Minimal RFC4180-ish CSV parser: quoted fields, escaped "" quotes, CRLF or LF. */
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  const pushField = () => { row.push(field); field = ""; };
  const pushRow = () => { pushField(); rows.push(row); row = []; };
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else field += ch;
      continue;
    }
    if (ch === '"') { inQuotes = true; continue; }
    if (ch === ",") { pushField(); continue; }
    if (ch === "\r") continue;
    if (ch === "\n") { pushRow(); continue; }
    field += ch;
  }
  if (field !== "" || row.length) pushRow();
  return rows;
}

function rowsToObjects(csvText) {
  const table = parseCsv(csvText);
  if (table.length === 0) return { fieldnames: [], rows: [] };
  const fieldnames = table[0];
  const rows = table.slice(1).map((cells) => {
    const obj = {};
    fieldnames.forEach((name, idx) => { obj[name] = cells[idx] ?? ""; });
    return obj;
  });
  return { fieldnames, rows };
}

function parseTime(value) {
  if (!TZ_RE.test(value || "")) throw new Error("timestamp must include a timezone");
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error("timestamp must include a timezone");
  return date;
}

/** Same rules as fifo_pick_evidence.py's check_rows: one pass for row-level
 * problems, then a per-SKU pass flagging a newer-received lot picked before
 * an older-received lot from the same SKU was picked. */
function checkRows(rows) {
  const observations = [];
  const bySku = new Map();

  rows.forEach((row, idx) => {
    const number = idx + 2; // header occupies row 1
    const missing = REQUIRED.filter((field) => !(row[field] || "").trim());
    if (missing.length) {
      observations.push({ row: number, kind: "missing-data", fields: missing });
      return;
    }
    let received;
    let picked;
    try {
      received = parseTime(row.received_at);
      picked = parseTime(row.picked_at);
    } catch {
      observations.push({ row: number, kind: "invalid-timestamp" });
      return;
    }
    if (picked < received) {
      observations.push({ row: number, kind: "time-order", message: "picked_at precedes received_at" });
    }
    if (!bySku.has(row.sku)) bySku.set(row.sku, []);
    bySku.get(row.sku).push({ number, row, received, picked });
  });

  for (const items of bySku.values()) {
    for (const item of items) {
      for (const other of items) {
        if (other.received < item.received && other.picked > item.picked) {
          observations.push({
            row: item.number,
            kind: "fifo-exception",
            sku: item.row.sku,
            order_id: item.row.order_id,
            older_row: other.number,
            older_order_id: other.row.order_id,
          });
        }
      }
    }
  }
  return observations;
}

function describeObservation(obs) {
  switch (obs.kind) {
    case "missing-data":
      return `missing required value${obs.fields.length > 1 ? "s" : ""}: ${obs.fields.join(", ")}`;
    case "invalid-timestamp":
      return "received_at or picked_at is missing, unparsable, or has no timezone";
    case "time-order":
      return obs.message;
    case "fifo-exception":
      return `SKU ${obs.sku}: order ${obs.order_id} was picked before older order ${obs.older_order_id} (row ${obs.older_row}), which arrived earlier and was still picked later`;
    default:
      return obs.kind;
  }
}

/** Builds the full evidence report from raw CSV text and a display file name. */
function buildReport(csvText, fileName) {
  const { fieldnames, rows } = rowsToObjects(csvText);
  const missingHeaders = REQUIRED.filter((field) => !fieldnames.includes(field));
  if (missingHeaders.length) {
    throw new Error("missing required columns: " + missingHeaders.join(", "));
  }
  const observations = checkRows(rows);
  return {
    generatedOn: new Date().toISOString().slice(0, 10),
    fileName: fileName || "picks.csv",
    rowsChecked: rows.length,
    status: observations.length ? "observations" : "no-observations",
    observations,
    limitations: LIMITATIONS,
  };
}

function toMarkdown(report) {
  const lines = [
    "# FIFO pick evidence",
    "",
    `Checked \`${report.fileName}\` on ${report.generatedOn}: **${report.rowsChecked} rows**, **${report.observations.length} observations**.`,
    "",
    "This report is an observation of the supplied rows, not an audit conclusion or compliance determination.",
    "",
  ];
  if (report.observations.length === 0) {
    lines.push("No observations -- nothing in this pick log needed a closer look.");
  } else {
    lines.push("## Observations", "", "| Row | Kind | Detail |", "|---|---|---|");
    for (const obs of report.observations) {
      lines.push(`| ${obs.row} | ${obs.kind} | ${describeObservation(obs).replace(/\|/g, "\\|")} |`);
    }
  }
  lines.push("", "## Limitations", "");
  for (const limitation of report.limitations) lines.push(`- ${limitation}`);
  lines.push(
    "",
    "**No warranty.** This tool is provided free and as-is, without warranty of any kind, express or implied. It is not engineering, legal, tax, financial, or compliance advice. **You are responsible for reviewing and verifying its output before relying on it**, and for meeting any obligation it helps you prepare for. To the maximum extent permitted by law, the authors accept no liability for any loss or damage arising from its use.",
  );
  return lines.join("\n") + "\n";
}

function toJson(report) {
  return JSON.stringify(report, null, 2) + "\n";
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    REQUIRED,
    parseCsv,
    rowsToObjects,
    parseTime,
    checkRows,
    describeObservation,
    buildReport,
    toMarkdown,
    toJson,
    LIMITATIONS,
  };
}

style.css.text:
:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --fg: #1a1a1a;
  --muted: #5f6368;
  --border: #e2e2e2;
  --accent: #2563eb;
  --good: #16a34a;
  --warn: #d97706;
  --card-bg: #f8f9fa;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --fg: #f1f2f4;
    --muted: #9aa0a6;
    --border: #2c2f34;
    --card-bg: #1c1f24;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  line-height: 1.5;
}

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

.hero {
  text-align: center;
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 0.5rem;
}

.tagline {
  color: var(--muted);
  font-size: 1.05rem;
  margin: 0 auto;
  max-width: 56ch;
}

.tagline code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.drop-zone {
  border: 2px dashed var(--border);
  border-radius: 12px;
  padding: 1.75rem 1.25rem;
  text-align: center;
  background: var(--card-bg);
}

.drop-zone.dragover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--card-bg));
}

.drop-zone p {
  margin: 0.4rem 0;
  color: var(--muted);
}

.file-label {
  display: inline-block;
  padding: 0.6rem 1.1rem;
  font-weight: 600;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.file-label input[type="file"] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
}

.or-line {
  font-size: 0.9rem;
}

#lockfile-paste {
  width: 100%;
  font-family: var(--mono);
  font-size: 0.85rem;
  padding: 0.6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  resize: vertical;
}

#parse-pasted {
  margin-top: 0.6rem;
  padding: 0.6rem 1.1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

#parse-pasted:hover,
.file-label:hover {
  filter: brightness(1.08);
}

.example-line {
  text-align: center;
  font-size: 0.95rem;
  opacity: 0.85;
  max-width: 50rem;
  margin: 0.9rem auto 0;
}

.link-button {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
}

.link-button:hover {
  filter: brightness(1.3);
}

.link-button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.error {
  text-align: center;
  color: #dc2626;
  font-weight: 600;
}

.summary-card {
  display: flex;
  justify-content: center;
  gap: 2rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  margin: 1.5rem 0 1rem;
  background: var(--card-bg);
}

.summary-stat {
  text-align: center;
}

.summary-number {
  display: block;
  font-size: 2rem;
  font-weight: 800;
}

.summary-number.production { color: var(--good); }
.summary-number.build-only { color: var(--warn); }

.summary-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.report-actions {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.report-actions button {
  padding: 0.55rem 1rem;
  font-size: 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
}

.report-actions button:hover {
  border-color: var(--accent);
}

.table-wrap {
  overflow-x: auto;
}

.component-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.component-table th,
.component-table td {
  text-align: left;
  padding: 0.55rem 0.6rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.component-table code {
  font-family: var(--mono);
  font-size: 0.85em;
}

.component-table .reason {
  color: var(--muted);
}

.badge {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
}

.badge.production {
  background: color-mix(in srgb, var(--good) 18%, transparent);
  color: var(--good);
}

.badge.build-only {
  background: color-mix(in srgb, var(--warn) 18%, transparent);
  color: var(--warn);
}

.disclaimer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  font-size: 0.9rem;
  color: var(--muted);
}

.disclaimer h2 {
  font-size: 1rem;
  color: var(--fg);
}

.disclaimer code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.footer {
  margin-top: 2rem;
  text-align: left;
  font-size: 0.85rem;
  color: var(--muted);
}

.footer p {
  margin: 0.75rem 0;
}

.privacy {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.75rem 0;
}

usage.js.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No pick-log contents, order IDs, or SKUs --
// just an event name and a day, kept in this browser's own localStorage.
// Nothing is sent anywhere; there is no server for it to go to. Off-switchable,
// and honors Do Not Track / Global Privacy Control.

const STORAGE_KEY = "fifo-pick-evidence:usage";
const OPT_OUT_KEY = "fifo-pick-evidence:usage:off";

function hasStorage() {
  try { return typeof localStorage !== "undefined"; } catch { return false; }
}

function browserOptedOut() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

function isUsageEnabled() {
  if (!hasStorage() || browserOptedOut()) return false;
  try { return localStorage.getItem(OPT_OUT_KEY) !== "1"; } catch { return false; }
}

function setUsageEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch { /* usage must never affect the report */ }
}

function recordUsage(eventName) {
  if (!isUsageEnabled() || !eventName) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const events = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch { /* private browsing and full storage are expected */ }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { isUsageEnabled, setUsageEnabled, recordUsage, STORAGE_KEY, OPT_OUT_KEY };
}
